const CLICK_SFX = 'data:audio/wav;base64,';

function useSound() {
  const ctx = React.useRef(null);
  const buf = React.useRef(null);

  React.useEffect(() => {
    const audio = new Audio(CLICK_SFX);
    audio.volume = 0.45;
    buf.current = audio;
  }, []);

  function play() {
    try {
      const a = new Audio(CLICK_SFX);
      a.volume = 0.45;
      a.play().catch(()=>{});
    } catch(e) {}
  }

  return play;
}

Object.assign(window, { useSound, CLICK_SFX });

